export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const safeURL=u=>{try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return ''}};
const beijingTime=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
export const stamp=s=>{if(typeof s!=='string'||!s)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(s)){const [,month,day]=s.split('-');return `${Number(month)} 月 ${Number(day)} 日`;}if(!/T.*(?:Z|[+-]\d{2}:\d{2})$/.test(s))return '';const date=new Date(s);if(!Number.isFinite(date.getTime()))return '';const parts=Object.fromEntries(beijingTime.formatToParts(date).map(p=>[p.type,p.value]));return `${Number(parts.month)} 月 ${Number(parts.day)} 日 ${parts.hour}:${parts.minute}（北京时间）`;};
export const links=urls=>urls.filter(safeURL).map((u,n)=>`<a href="${esc(safeURL(u))}" target="_blank" rel="noopener noreferrer">${esc(new URL(u).hostname)}${n?' · '+(n+1):''} ↗</a>`).join('');
export const paragraphs=s=>String(s||'').split(/\n\n/).map(p=>`<p>${esc(p)}</p>`).join('');
export function itemHTML(i,n=0,hero=false){return `<article class="news" data-item="${esc(i.event_id)}" data-group="${esc(i.group)}"><div class="news-top"><span class="num">${String(n+1).padStart(2,'0')}</span><span class="tag">${esc(i.groupLabel)}</span>${stamp(i.event_at)?`<time>${esc(stamp(i.event_at))}</time>`:'<span>固定栏目</span>'}</div><h3>${esc(i.title)}</h3><p class="excerpt">${esc((i.summary||'').split('\n\n')[0])}</p><details class="news-details"><summary>展开全文 <span>＋</span></summary><div class="fulltext">${paragraphs(i.summary)}</div><div class="sources">${links(i.urls||[])}</div></details></article>`}
export function offerHTML(o){return `<details class="offer"><summary><strong>${esc(o.provider)}</strong><span>${esc(o.kindLabel)}</span></summary><div class="offer-body">${o.models.length?`<p class="models">${o.models.map(esc).join(' · ')}</p>`:'<p>未核实可单独选择的免费模型。</p>'}${(o.other_models||[]).map(g=>`<p>${esc(g.names.join('、'))}：${esc(g.quota)}</p>`).join('')}<p>额度：${esc(o.quota)}</p>${['conditions','expiry','privacy','caution'].filter(k=>o[k]).map(k=>`<p>${({conditions:'条件',expiry:'有效期',privacy:'隐私',caution:'注意'})[k]}：${esc(o[k])}</p>`).join('')}<div class="sources">${links(o.sources)}</div></div></details>`}
export function matches(i,q,group='all'){return(group==='all'||i.group===group)&&(!q||JSON.stringify(i).toLowerCase().includes(q.toLowerCase().trim()))}
